/**
 * Whether one schema-3 fact group is carrying values in this snapshot.
 *
 * The set is closed at two members on purpose. A reader needs to tell "the producer read this and
 * here it is" from "the producer could not read this", and nothing else about a group is knowable
 * without the producer guessing. Freshness is not a third member: how old a document is, is what
 * {@code emittedAt} answers, for the whole document at once, and a per-group freshness claim would
 * be an inference this plugin is not allowed to make.
 *
 * A group is {@link #SUPPORTED} exactly when its values are present, and {@link #UNAVAILABLE}
 * exactly when they are null. Nothing is ever filled in with a default to make a group look
 * supported.
 */
enum TelemetryCapability
{
	SUPPORTED("supported"),
	UNAVAILABLE("unavailable");

	private final String exported;

	TelemetryCapability(String exported)
	{
		this.exported = exported;
	}

	/** The lowercase name written into the document. */
	String exported()
	{
		return exported;
	}

	static TelemetryCapability of(boolean present)
	{
		return present ? SUPPORTED : UNAVAILABLE;
	}
}

