package com.facette.telemetry;

import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.channels.FileChannel;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.CopyOption;
import java.nio.file.DirectoryStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import java.nio.file.attribute.FileTime;
import java.util.Objects;
import java.util.concurrent.locks.Lock;
import java.util.function.BooleanSupplier;
import java.util.function.LongSupplier;

/**
 * Writes a snapshot to its local target file as one complete replacement. Each publication is
 * serialized into a temporary sibling, forced to disk, closed, and only then moved over the target,
 * atomically where the filesystem supports it. A reader sees either the previous snapshot or the new
 * one, never a partial document.
 */
final class TelemetrySnapshotWriter
{
	// A backstop rather than the schema's bound: every exported string is length-bounded and every
	// exported collection is fixed-size or bounded by a game enumeration, so no document the plugin
	// can build comes near this. Schema 3's measured worst case is pinned in TelemetrySnapshotTest,
	// and this number is chosen to sit above it with room to spare. It was 16,384 for schema 2,
	// whose largest reachable document was around half of that; schema 3's per-skill block and offer
	// slots take the measured worst case past that figure, so the guard moves with the schema rather
	// than the schema being trimmed to fit a number.
	static final int MAX_SNAPSHOT_BYTES = 24_576;

	// Versioned, so schema 3 lands beside an earlier schema's file rather than on top of it. This
	// writer sweeps only its own prefix, so a state-v1.json or state-v2.json alongside it is never
	// touched: an older file simply stops being updated and goes stale, which is what a reader of
	// that schema already knows how to notice.
	static final String TARGET_FILE_NAME = "state-v3.json";

	private static final String TEMP_PREFIX = "state-v3-";
	private static final String TEMP_SUFFIX = ".tmp";

	// Well above the publish interval, so a second client's in-flight file is never deleted.
	private static final long STALE_TEMP_AGE_MILLIS = 60_000L;

	@FunctionalInterface
	interface Mover
	{
		void move(Path source, Path target, CopyOption... options) throws IOException;
	}

	static final class SnapshotTooLargeException extends IOException
	{
		private static final long serialVersionUID = 1L;

		SnapshotTooLargeException(int size)
		{
			super("Snapshot of " + size + " bytes exceeds the " + MAX_SNAPSHOT_BYTES + " byte limit");
		}
	}

	/**
	 * Thrown when a staged snapshot is abandoned because a newer plugin run started while this one was
	 * writing. An IOException on purpose: every caller already treats a failed write as "did not reach
	 * the file", so the sequence and heartbeat bookkeeping are left untouched.
	 */
	static final class CommitNotAuthorizedException extends IOException
	{
		private static final long serialVersionUID = 1L;

		CommitNotAuthorizedException(Path target)
		{
			super("Publication is no longer authorized to replace " + target);
		}
	}

	private final Path directory;
	private final Path target;
	private final Mover mover;
	private final LongSupplier clock;

	private boolean sweptStaleTemporaryFiles;

	TelemetrySnapshotWriter(Path directory)
	{
		this(directory, Files::move, System::currentTimeMillis);
	}

	TelemetrySnapshotWriter(Path directory, Mover mover, LongSupplier clock)
	{
		this.directory = Objects.requireNonNull(directory, "directory");
		this.target = directory.resolve(TARGET_FILE_NAME);
		this.mover = Objects.requireNonNull(mover, "mover");
		this.clock = Objects.requireNonNull(clock, "clock");
	}

	Path getTarget()
	{
		return target;
	}

	/**
	 * Publishes one snapshot and returns the number of UTF-8 bytes written. Everything slow touches
	 * only the temporary file. Commit authority is checked after that and the target replaced, so a
	 * slow publication finds out a newer run took over before it does damage. The lock covers that
	 * check and the replacement only, never staging.
	 */
	int write(TelemetrySnapshot snapshot, Lock commitLock, BooleanSupplier commitAuthorized)
		throws IOException
	{
		Objects.requireNonNull(commitLock, "commitLock");
		Objects.requireNonNull(commitAuthorized, "commitAuthorized");
		byte[] payload = snapshot.toJsonBytes();
		if (payload.length > MAX_SNAPSHOT_BYTES)
		{
			throw new SnapshotTooLargeException(payload.length);
		}

		Files.createDirectories(directory);
		sweepStaleTemporaryFilesOnce();

		Path temp = Files.createTempFile(directory, TEMP_PREFIX, TEMP_SUFFIX);
		try
		{
			try (FileChannel channel = FileChannel.open(temp,
				StandardOpenOption.WRITE, StandardOpenOption.TRUNCATE_EXISTING))
			{
				ByteBuffer buffer = ByteBuffer.wrap(payload);
				while (buffer.hasRemaining())
				{
					channel.write(buffer);
				}
				channel.force(true);
			}

			commitLock.lock();
			try
			{
				if (!commitAuthorized.getAsBoolean())
				{
					throw new CommitNotAuthorizedException(target);
				}

				replaceTarget(temp);
			}
			finally
			{
				commitLock.unlock();
			}
			return payload.length;
		}
		finally
		{
			// However the move ended, this attempt leaves no temporary file of ours behind.
			Files.deleteIfExists(temp);
		}
	}

	private void replaceTarget(Path temp) throws IOException
	{
		try
		{
			mover.move(temp, target,
				StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
		}
		catch (AtomicMoveNotSupportedException | UnsupportedOperationException e)
		{
			// The only fallback: move the already-complete sibling with replacement. The target is
			// still never streamed into.
			mover.move(temp, target, StandardCopyOption.REPLACE_EXISTING);
		}
	}

	private void sweepStaleTemporaryFilesOnce() throws IOException
	{
		if (sweptStaleTemporaryFiles)
		{
			return;
		}
		sweptStaleTemporaryFiles = true;
		sweepStaleTemporaryFiles();
	}

	/**
	 * Removes temporary files this writer owns that a previous run abandoned, which happens when a
	 * client is killed mid-write. Only this writer's own naming and only past the stale age, so a
	 * second client's in-flight file is never removed.
	 */
	void sweepStaleTemporaryFiles() throws IOException
	{
		long cutoff = clock.getAsLong() - STALE_TEMP_AGE_MILLIS;
		try (DirectoryStream<Path> entries =
				 Files.newDirectoryStream(directory, TEMP_PREFIX + "*" + TEMP_SUFFIX))
		{
			for (Path entry : entries)
			{
				try
				{
					FileTime modified = Files.getLastModifiedTime(entry);
					if (modified.toMillis() < cutoff)
					{
						Files.deleteIfExists(entry);
					}
				}
				catch (IOException e)
				{
					// Not worth failing a publication over.
				}
			}
		}
	}
}

